import{_ as o,o as d,c,a3 as t}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"哨兵（Sentinel）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/sentinel.md","filePath":"zh/sentinel.md"}'),a={name:"zh/sentinel.md"};function s(i,e,l,n,r,p){return d(),c("div",null,[...e[0]||(e[0]=[t(`<h1 id="哨兵-sentinel" tabindex="-1">哨兵（Sentinel） <a class="header-anchor" href="#哨兵-sentinel" aria-label="Permalink to &quot;哨兵（Sentinel）&quot;">​</a></h1><p>Meta 把 Muse 的安全模型描述为一个独立的「哨兵」（Sentinel）智能体，坐在模型和它的工具之间：审批敏感操作、让凭据不落入模型之手、记录发生了什么。nanoMuse 实现了同样的分离。智能体从不自己执行工具，而是把调用交给 <code>Sentinel.guard()</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent ──► Sentinel.guard() ──► policy ──► approval (if needed) ──► vault.resolve ──► execute</span></span>
<span class="line"><span>agent ◄── redact(result)   ◄── taint bookkeeping ◄─────────────────────────────────────┘</span></span></code></pre></div><p>代码：<code>nanomuse/sentinel/gate.py</code>（关口）、<code>policy.py</code>（决策）、<code>audit.py</code>（日志）。保险库在 <code>nanomuse/vault/</code>。</p><h2 id="risk-levels" tabindex="-1">风险级别 <a class="header-anchor" href="#risk-levels" aria-label="Permalink to &quot;风险级别 {#risk-levels}&quot;">​</a></h2><p>每个工具都声明一个静态的 <code>risk</code>：</p><table tabindex="0"><thead><tr><th>级别</th><th>含义</th><th>例子</th></tr></thead><tbody><tr><td><code>safe</code></td><td>可逆、本地</td><td><code>files</code>（工作区之内）、<code>web_search</code>、<code>remember</code>、<code>goals</code>、<code>contacts</code>、<code>skills</code>（列出、使用）、<code>phone_screen</code></td></tr><tr><td><code>moderate</code></td><td>触及外部或改变状态</td><td><code>web_fetch</code>、<code>python_execute</code>、<code>read_emails</code>、<code>browser</code>、<code>forget</code>、<code>phone_act</code></td></tr><tr><td><code>sensitive</code></td><td>难以撤销或外部可见</td><td><code>shell</code>、<code>send_email</code>、<code>skills</code>（保存、删除——技能是模型以后会照着做的长期指令，所以写一个技能总是会问）</td></tr></tbody></table><p>工具可以在 <code>assess()</code> 里为某一次调用提高级别：<code>shell</code> 遇到 <code>rm -rf</code>、<code>sudo</code>、<code>curl | sh</code> 这类模式会附上一条警告；<code>python_execute</code> 对纯计算和工作区内的文件是 <code>moderate</code>——前提是沙箱在工作；没有沙箱时（macOS、Windows、没装 bubblewrap 的 Linux 机器）每个脚本都是 <code>sensitive</code>，因为静态检查是仅剩的一道墙——而当代码访问网络、启动其他程序、读环境变量、删文件或触及工作区之外的路径时是 <code>sensitive</code>，原因写在卡片上；<code>web_fetch</code> 直接拒绝私有地址和回环地址，每一跳重定向都查；<code>phone_act</code> 在一次点击的 <code>label</code>——操作器对手指下面是什么的描述——含有 确认支付、转账、提交订单、发送、删除 或 <code>[gui] sensitive_words</code> 里的另一个词时，或者一步同时输入并提交时，是带警告的 <code>sensitive</code>；没有 label 的点击自带一条警告（<a href="./gui">gui.md</a>）。工具还声明 <code>reads_private_data</code>（污染这段对话）和 <code>egress</code>，可选带 <code>egress_target</code>（这次调用把数据发往的主机；<code>shell</code> 和 <code>python_execute</code> 未知；手机上是 App 的 id），供污点追踪使用。</p><p><code>shell</code> 和 <code>python_execute</code> 启动的子进程拿到的是清洗过的环境：名字像凭据的变量（<code>*KEY*</code>、<code>*TOKEN*</code>、<code>*SECRET*</code>、<code>*PASSW*</code>、<code>*CREDENTIAL*</code>、<code>*AUTH*</code>、<code>*COOKIE*</code>、<code>*SESSION*</code>）、所有 <code>NANOMUSE_</code>、<code>AWS_</code>、<code>AZURE_</code>、<code>GOOGLE_</code>、<code>GH_</code>、<code>GITHUB_</code>、<code>NPM_</code> 开头的，再加 <code>SSH_AUTH_SOCK</code>，都在子进程启动前移除，所以模型写的代码读不到模型自己的 API key，也读不到 <code>os.environ</code> 里的保险库密钥。这两个工具都不接受 <code>{{vault:NAME}}</code> 占位符——带占位符的命令会被拒绝并说明原因，而不是拿字面文本去跑；保险库里的值只送达用它们配置的连接器。编程 CLI（<code>coding_tool</code>：Codex、Claude Code、Cursor）拿到同样清洗过的环境，再加上它们各自的账号变量（<code>OPENAI_*</code>/<code>CODEX_*</code>、<code>ANTHROPIC_*</code>/<code>CLAUDE_*</code>——当 <code>CLAUDE_CODE_USE_BEDROCK</code>/<code>_VERTEX</code> 这么要求时还有云凭据——<code>CURSOR_*</code>），运行时的其他东西一概没有。</p><h2 id="the-sandbox" tabindex="-1">沙箱 <a class="header-anchor" href="#the-sandbox" aria-label="Permalink to &quot;沙箱 {#the-sandbox}&quot;">​</a></h2><p>Meta Muse 给每个用户的智能体一台独立的 VM。nanoMuse 跑在你的机器上，所以在 Linux 上做了退而求其次的事：每一次 <code>shell</code> 和 <code>python_execute</code> 调用都在自己的命名空间里运行，由 <a href="https://github.com/containers/bubblewrap" target="_blank" rel="noreferrer">bubblewrap</a> 创建（Flatpak 背后的那个工具；无需特权，<code>apt install bubblewrap</code> / <code>dnf install bubblewrap</code>）。箱子里面：</p><ul><li>工作区（和 <code>agent.extra_roots</code>）是仅有的可写位置——<code>/usr</code>、<code>/etc</code>、<code>/opt</code>、<code>/var</code> 只读，<code>/tmp</code> 是这次调用私有的，<code>/proc</code> 和 <code>/dev</code> 是全新的；</li><li>你的家目录不存在，连带保险库、数据目录、ssh 密钥、云凭据和浏览器配置都不存在。仅有的例外：正在运行的 Python 所在的目录（venv 或 <code>uv</code> 管理的解释器常常在家目录下），只读，这样 <code>python_execute</code> 用的解释器和包和 nanoMuse 一样；技能文件夹（内置的和你的），只读，这样技能的脚本和参考文件能在里面运行和读取；还有你刻意共享的——<code>[sandbox] share_read_only</code> 给程序（装着 node 和飞书 CLI 的 <code>~/.nvm</code>），<code>share</code> 给工具还必须写入的状态（它的登录态，<code>~/.lark-cli</code> 和 <code>~/.local/share/lark-cli</code>）。你家目录下共享的目录在箱子自己的家目录下同一位置也看得到，所以到 <code>$HOME</code> 里找东西的工具能找到；家目录的其余部分留在外面。位于工作区之内的数据目录会被遮住；</li><li><strong>没有网络</strong>，除非这次调用被评估为需要它：运行网络程序（<code>curl</code>、<code>wget</code>、<code>pip</code>、<code>git</code>、<code>ssh</code>、<code>npm</code>、<code>docker</code>……）、含有 URL 或主机名、或者写了 <code>network=true</code> 的 <code>shell</code> 命令；导入网络模块（<code>requests</code>、<code>httpx</code>、<code>socket</code>、<code>urllib</code>……）或启动其他程序的 <code>python_execute</code> 脚本。其他一切只带回环接口运行。因为没有网络而失败的命令，结果里会附一条说明，模型可以带 <code>network=true</code> 再跑一次——那就成了一次外发调用，和其他任何调用一样过同样的审查；</li><li>进程树、IPC、UTS 和 cgroup 命名空间都是分开的；<code>HOME</code> 和 <code>TMPDIR</code> 指向私有的 <code>/tmp</code>；设置了 <code>NANOMUSE_SANDBOX=bwrap</code>，脚本能据此判断。</li></ul><p>这改变了「外发」对 <code>shell</code> 的含义：没有沙箱时，每条 shell 命令都被当作可能访问网络的（读过私密数据之后就会问）；有沙箱时，只有拿到网络的命令才算。读完邮件后一条装在箱子里的 <code>ls</code> 什么也发不出去，所以不会因为这个理由问——但它仍是 <code>sensitive</code>，在 <code>ask</code> 模式下仍会问，和每条 shell 命令一样。</p><p><code>[sandbox] mode</code> 是 <code>auto</code>（默认：bubblewrap 装了并且能在这里创建命名空间时就用）、<code>bwrap</code>（坚持用——用不了时 <code>nanomuse doctor</code> 失败，日志说明原因）或 <code>off</code>。在它跑不起来的地方——macOS、Windows、大多数 Docker 容器（默认的 seccomp 配置挡住了非特权用户命名空间，这没关系：容器本身就是箱子）——命令照旧运行，带着清洗过的环境，以工作区为工作目录，「设置 → 安全」会说明这一点。<code>nanomuse doctor</code> 打印沙箱那一行；设置 API 把它放在 <code>sandbox</code> 下。</p><p><strong>Ubuntu 24.04 及其衍生版</strong>用 AppArmor 限制非特权用户命名空间：<code>kernel.apparmor_restrict_unprivileged_userns=1</code> 让没有自己 AppArmor 配置的程序创建的命名空间没有任何 capability。看机器不同，bubblewrap 要么直接失败（<code>bwrap: setting up uid map: Permission denied</code>），要么箱子建起来了但建不了它的网络命名空间（<code>bwrap: loopback: Failed RTM_NEWADDR: Operation not permitted</code>）。第二种情况下 nanoMuse 保留文件系统的箱子，放弃网络：状态行写着「网络未被阻断」，<code>shell</code> 命令按没有箱子的方式判断——每一条都可能访问外部。两种情况的解法都是 <code>/usr/bin/bwrap</code> 的标准配置，Ubuntu 25.04 随 <code>apparmor</code> 提供，24.04 在 <code>apparmor-profiles</code> 里（Flatpak 出过一次回归之后它被从默认集合里拿掉了）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apparmor-profiles</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0644</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/share/apparmor/extra-profiles/bwrap-userns-restrict</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/apparmor.d/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apparmor_parser</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/apparmor.d/bwrap-userns-restrict</span></span></code></pre></div><p><code>nanomuse doctor</code> 会指出是这种情况。关掉限制（<code>sudo sysctl -w kernel.apparmor_restrict_unprivileged_userns=0</code>）也行，但削弱的是整台机器，不只是箱子。</p><h2 id="decision-order" tabindex="-1">决策顺序 <a class="header-anchor" href="#decision-order" aria-label="Permalink to &quot;决策顺序 {#decision-order}&quot;">​</a></h2><p>每次调用，第 1 到第 4 步里第一个匹配的步骤给出决定；第 5、6 步随后对每个决定都会检查，只能把「允许」改成「询问」：</p><ol><li><strong><code>deny_tools</code></strong> → 拒绝。</li><li><strong><code>[[sentinel.rules]]</code></strong>：<code>tool</code>（glob，<code>*</code> 表示任意）加 <code>match</code>，一个参数名 → glob 模式的映射，拿 <code>str(value)</code> 来匹配。第一条匹配的规则生效，给出它的 <code>action</code>。</li><li><strong><code>always_allow_tools</code> / <code>always_ask_tools</code></strong>。</li><li><strong>风险 × 模式</strong>，前面都没有匹配时：</li></ol><table tabindex="0"><thead><tr><th>模式</th><th><code>safe</code></th><th><code>moderate</code></th><th><code>sensitive</code></th></tr></thead><tbody><tr><td><code>ask</code>（默认）</td><td>允许</td><td>允许</td><td>询问</td></tr><tr><td><code>strict</code></td><td>允许</td><td>询问</td><td>询问</td></tr><tr><td><code>auto</code></td><td>允许</td><td>允许</td><td>允许</td></tr></tbody></table><ol start="5"><li><strong>污点</strong>：到这里的决定是允许，这段对话已被污染，<strong>而且</strong>这次调用外发到不在 <code>egress_allowlist</code> 里的主机（或目的地未知）→ 询问，不论这个允许来自模式、<code>always_allow_tools</code> 还是一条规则。目的地已知时审批卡片会显示它。</li><li><strong>警告</strong>：带警告的调用（<code>rm -rf</code>、<code>sudo</code>、<code>curl | sh</code>、读环境变量或删文件的代码）绝不会被模式或 <code>always_allow_tools</code> 放行；它会问。只有一条明确的 <code>allow</code> 规则能覆盖这一点。</li></ol><p><code>auto</code> 仍然遵守 <code>deny_tools</code>、deny 规则、第 5 步和第 6 步。污点规则在每种模式下都成立：一段对话读过邮件、日历、联系人或其他私密来源之后，要把数据发往 <code>egress_allowlist</code> 之外主机的调用会询问，<code>auto</code> 不会把这个问题改成放行。<code>nanomuse daemon</code>、<code>--auto</code> 和 App 里的「放手」设置用的就是它，后台的目标检查也是，所以无人值守的运行里出现危险命令或读过私密数据后的外发时，它变成动态里的一张卡片，而不是直接跑掉。<code>nanomuse daemon</code> 旁边没有人：仍需要审批的那一步会被拒绝并留下说明，模型继续做它能做的。</p><h2 id="approvals" tabindex="-1">审批 <a class="header-anchor" href="#approvals" aria-label="Permalink to &quot;审批 {#approvals}&quot;">​</a></h2><p>决定是「询问」时，界面（控制台，或 App 里的审批卡片）显示工具、调用的摘要、导致这次调用的你的请求（「目的」）、精确的参数、风险级别和原因。你可以拒绝，或者带一个范围允许：</p><table tabindex="0"><thead><tr><th>回答</th><th>效果</th></tr></thead><tbody><tr><td>拒绝</td><td>工具不运行；模型收到一个「Sentinel blocked」结果，并被告知不要重试同一个调用</td></tr><tr><td>一次</td><td>只这一次；什么都不记</td></tr><tr><td>本次对话</td><td>只要这次调用来自的聊天还在（它之后的每一轮都覆盖；删除或清空聊天就结束；重启后不保留）——手机 App 一直有的那个中间范围；对 <code>shell</code> 来说覆盖的是整个工具，不只是当前命令里的程序。聊天之外的运行（<code>nanomuse run</code>、定时任务）自成一个对话</td></tr><tr><td>直到重启</td><td>直到进程退出</td></tr><tr><td>24 小时</td><td>带过期时间持久化在 <code>&lt;data_dir&gt;/approvals.json</code> 里</td></tr><tr><td>总是</td><td>持久化，直到你撤销</td></tr></tbody></table><p>审批是一项能力，不是一种心情。它绑定一个<strong>授权键</strong>：工具加上这次调用触及的东西——<code>web_fetch:example.com</code>、<code>send_email:alice@example.com</code>、<code>shell:git</code>、<code>browser:booking.com</code>。允许 <code>git</code> 命令用于本次会话，对 <code>curl</code> 什么也没说；<code>git status | head</code> 这样的管道需要每个程序都被覆盖（批准它时每个程序分别获得授权），发给两个人的邮件需要两个收件人都被覆盖。唯一有意为之的例外是 <code>shell</code> 上的「本次对话」：现在需要 <code>git</code> 的任务，一会儿就会需要 <code>ls</code> 和 <code>wc</code>，所以这个回答覆盖对话余下时间里的整个 shell——而目的地（收件人、主机）即使在其中也仍然绑定。没有明确目标的工具（<code>python_execute</code>、一个 MCP 工具）整体授权，而对能访问网络的任意代码，哨兵只提供「一次」和「本次对话」。带警告的调用（<code>rm -rf</code>、<code>sudo</code>、<code>curl | sh</code>）一次一批——长期许可永远不覆盖它。</p><p>你授出的一切都列在 App 里形象下方（「权限」），每一项有自己的撤销按钮；<code>DELETE /api/approvals/grants/{key}</code> 和 <code>DELETE /api/approvals</code> 从 API 做同样的事，<code>nanomuse chat</code> 的 <code>/forget-approvals</code> 在控制台里清掉它们。</p><p>在 App 里，没人回答的卡片在 <code>server.approval_timeout</code> 秒（默认一小时）后超时，算作拒绝。卡片等待期间智能体照常接收新消息。服务器停止时仍在等待的卡片在重启后标记为过期；它们背后的那次运行没有了。</p><h2 id="taint-tracking" tabindex="-1">污点追踪 <a class="header-anchor" href="#taint-tracking" aria-label="Permalink to &quot;污点追踪 {#taint-tracking}&quot;">​</a></h2><p>读取私密数据（<code>read_emails</code>、<code>recall</code>、<code>contacts</code>、工作区之外的文件、标记了 <code>reads_private_data</code> 的 MCP 服务器）会把这段对话标记为已污染。从那以后，这段对话里任何把数据发往 <code>egress_allowlist</code> 之外主机的调用都需要审批，不论它的风险级别，也不论模式，<code>auto</code> 也一样。污点按对话记录：一个读过你邮件的侧边聊天不会让旁边的聊天跟着询问，清空或删除一段对话只会去掉它自己的污点。污点只放在内存里，重启后不保留，也不会跟着通过记忆或工作区文件跨过对话的数据走。这是对提示注入的实际防线：一个网页没法指使智能体把你的收件箱发到某处，而你事先看不到目的地。</p><p><code>nanomuse chat</code> 用 <code>/tainted</code> 显示状态；<code>/reset</code> 随对话一起清掉它，其他对话保持原样。默认白名单覆盖搜索、维基百科、GitHub 和 PyPI；按你自己的连接器改 <code>egress_allowlist</code>。你自己在设置里定下的目的地——<code>[connectors.search]</code> 下的搜索服务商，不管是哪家——和白名单同等对待：模型没法改它的指向，所以读过私密数据之后的搜索照样通过，和用 DuckDuckGo 时一样。</p><h2 id="credential-vault" tabindex="-1">凭据保险库 <a class="header-anchor" href="#credential-vault" aria-label="Permalink to &quot;凭据保险库 {#credential-vault}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nanomuse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EMAIL_PASSWORD</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # prompted; stored Fernet-encrypted in &lt;data_dir&gt;/vault.enc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nanomuse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                      # names only</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nanomuse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EMAIL_PASSWORD</span></span></code></pre></div><p>配置值——模型的 key、邮件、日历和联系人的链接、搜索的 key——用 <code>{{vault:NAME}}</code> 引用机密；模型看到的是占位符，连接器用真实值构建。工具参数<strong>不</strong>携带机密：没有任何正式工具选择接受（<code>accepts_secrets</code>），所以 <code>shell</code> 或 <code>python_execute</code> 调用里的 <code>{{vault:NAME}}</code> 会被拒绝并说明原因，而不是拿字面文本去跑（你自己的工具可以选择接受；哨兵会在执行前一刻替换）。如果某个机密出现在任何工具的输出里，模型读到之前它就被换回 <code>{{vault:NAME}}</code>。密钥是 <code>&lt;data_dir&gt;/vault.key</code>（首次使用时创建，权限 600）或 <code>NANOMUSE_VAULT_KEY</code>。</p><h2 id="audit-log" tabindex="-1">审计日志 <a class="header-anchor" href="#audit-log" aria-label="Permalink to &quot;审计日志 {#audit-log}&quot;">​</a></h2><p>每条用户消息、每轮模型输出、每个决策、审批、工具调用和结果都带 UTC 时间戳追加到 <code>&lt;data_dir&gt;/audit.jsonl</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nanomuse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # table</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nanomuse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # raw lines</span></span></code></pre></div><p>App 里的活动面板（点形象）读的是同一个文件。</p><h2 id="what-this-does-and-does-not-protect-against" tabindex="-1">它能防什么、不能防什么 <a class="header-anchor" href="#what-this-does-and-does-not-protect-against" aria-label="Permalink to &quot;它能防什么、不能防什么 {#what-this-does-and-does-not-protect-against}&quot;">​</a></h2><p>Meta Muse 把每个用户的智能体跑在各自的云端 VM 里，哨兵在 VM 之外。nanoMuse 跑在你的机器上，以你的用户身份，哨兵是同一个进程里的一个模块。这改变了这些保护措施能承诺什么。老实说：</p><p><strong>覆盖到的</strong></p><ul><li><em>模型做了你没要求的事。</em> 每个工具调用都过策略；敏感和危险的调用停下来等决定；许可限定在一个工具和一个目标上，可以撤销。</li><li><em>试图外泄数据的提示注入。</em> 私密数据一旦被读取，外发到白名单之外的任何主机都先询问，目的地写在卡片上。<code>web_fetch</code> 不能被指向回环、链路本地、私有或云元数据地址，经重定向也不行。</li><li><em>模型看到你的机密。</em> key 和密码放在加密的保险库里，以占位符进入工具调用；审批之后才替换，结果里再抹掉。子进程不继承看起来像凭据的环境变量，在沙箱里也读不到保险库、数据目录或你家目录下的任何其他东西。模型永远看不到 App 的访问令牌。</li><li><em>不知道发生了什么。</em> 一切都在 <code>audit.jsonl</code> 和「活动」视图里。</li></ul><p><strong>没覆盖到的——运行之前先知道</strong></p><ul><li><em>操作系统级隔离，在沙箱跑不起来的地方。</em> Linux 上有 bubblewrap 时，箱子里的命令只看得到工作区，够不着你的家目录，没有网络，除非调用声明需要（见<a href="#the-sandbox">沙箱</a>）；但 bubblewrap 命名空间不是 VM，内核漏洞或你批准的一次 <code>network=true</code> 调用，该是什么还是什么。其他所有地方 <code>shell</code> 和 <code>python_execute</code> 以你的身份运行：你批准的命令能做你能做的一切，模式检查只是绊线，对抗性脚本躲得开。如果工作区碰得到任何你丢了会心疼的东西，就在容器里或一个专用用户账号下运行 nanoMuse（Docker 镜像就是这样一种配置）。</li><li><em>磁盘上的保险库密钥。</em> 默认情况下 Fernet 密钥就放在保险库旁边（<code>vault.key</code>，权限 600）。能读你数据目录的人就能解开保险库。如果这对你重要，从密钥管理服务设置 <code>NANOMUSE_VAULT_KEY</code>。</li><li><em>DNS 重绑定。</em> <code>web_fetch</code> 在请求前检查解析出来的地址；一个片刻之后给出不同答案的恶意 DNS 服务器仍能把请求指向内部地址。污点规则和白名单限制了这样一次抓取能和什么组合起来。</li><li><em>糟糕的授权。</em> 「总是允许 <code>shell:curl</code>」就和它听起来的一样强。警告仍会问，但 <code>curl</code> 的目的地不会被检查。</li><li><em>App 所在的网络。</em> API 默认由 bearer token 保护，走明文 HTTP。别把端口暴露到互联网；用 Tailscale 或 TLS 反向代理。在「连接」屏里输入的机密走的就是这条连接。</li><li><em>模型服务商看到什么。</em> 每条记忆都在系统提示里发给聊天模型——记忆本来就是干这个的。聊天里附的图片在聊天模型接受图片时（<code>llm.vision</code>）作为图像内容发给它；文档在智能体用 <code>files</code> 读它之前哪儿也不去，读了之后它的文字就和所有工具结果走同一条路。开了按含义回忆时，每条记忆的文字也会发给 embedding 端点，每条一次，每条消息一次。当那是模型自己的端点时，没有新东西被分享；当它是另一个服务（<code>memory.embedding_base_url</code>）时，那个服务也看到你的记忆和消息——本地的 Ollama 是不与任何人分享的选择。embedding 调用不是工具调用，所以在污点规则之外；它们从不携带保险库的值。</li><li><em>审批疲劳。</em> 如果卡片看都不看就批，以上一切都帮不了你。</li></ul><p>和「覆盖到的」清单相矛盾的任何事都请报告——见 <a href="https://github.com/nano-muse/nanoMuse/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>。</p><h2 id="writing-a-safe-tool" tabindex="-1">写一个安全的工具 <a class="header-anchor" href="#writing-a-safe-tool" aria-label="Permalink to &quot;写一个安全的工具 {#writing-a-safe-tool}&quot;">​</a></h2><ul><li>设一个诚实的 <code>risk</code>；拿不准就 <code>moderate</code>。</li><li>输出可能包含用户私密数据时设 <code>reads_private_data = True</code>；调用会把数据发往任何地方时设 <code>egress = True</code>（主机已知时在 <code>assess()</code> 里给出 <code>egress_target</code>）。</li><li>重写 <code>assess()</code>，对危险的参数模式提高级别，并生成一段简短、人能读的 <code>summary</code>；审批卡片显示的就是它。</li><li>永远别自己读机密。确实需要的工具用 <code>accepts_secrets = True</code> 选择接受，让哨兵来解析 <code>{{vault:NAME}}</code> 占位符；内置工具都不这么做。</li><li>用 <code>ToolResult(error=...)</code> 返回错误，而不是抛异常；<code>safe_execute</code> 兜住其余的。</li></ul>`,48)])])}const k=o(a,[["render",s]]);export{u as __pageData,k as default};
